            var exported=PortableWorkspaceService.Create(new[]{profile,privateProfile},new[]{"cute-pastel","import-private","neon-blue"},local,catalog);Check(exported.ExcludedProfiles==1&&exported.ExcludedFavorites==1&&exported.Document.Favorites.Contains("cute-pastel"),"Private resource refs excluded; offline/uninstalled official favorites retained");
